We have,

\begin{aligned}
\sin \left(2 \cos ^{-1} \frac{\sqrt{5}}{3}\right) &=\sin \left\{\cos ^{-1}\left(2 \times\left(\frac{\sqrt{5}}{3}\right)^{2}-1\right)\right\} \\
&=\sin \left\{\cos ^{-1}\left(\frac{10}{9}-1\right)\right\} \\
&=\sin \left(\cos ^{-1} \frac{1}{9}\right)
\end{aligned}

\begin{aligned}
&=\sin \left\{\sin ^{-1} \sqrt{1-\left(\frac{1}{9}\right)^{2}}\right\} \\
&=\sin \left\{\sin ^{-1}\left(\frac{4 \sqrt{5}}{9}\right)\right\}=\frac{4 \sqrt{5}}{9}
\end{aligned}

We have,

\begin{gathered}
\sin \left(2 \sin ^{-1} \sqrt{\frac{63}{65}}\right) \\
=\sin \left\{\sin ^{-1}\left(2 \sqrt{\frac{63}{65}} \sqrt{1-\left(\sqrt{\frac{63}{65}}\right)^{2}}\right)\right\} ; \\
{\left[\because 2 \sin ^{-1} x=\sin ^{-1} 2 x \sqrt{1-x^{2}}\right]}
\end{gathered}

$=\sin \left\{\sin ^{-1}\left(2 \sqrt{\frac{63}{65}} \sqrt{1-\frac{63}{65}}\right)\right\}=\sin \left\{\sin ^{-1}\left(2 \sqrt{\frac{63}{65}} \times \sqrt{\frac{2}{65}}\right)\right\}=\sin \left\{\sin ^{-1} \frac{2 \sqrt{126}}{65}\right\}=\frac{2 \sqrt{126}}{65} \quad\left[\because \sin \left(\sin ^{-1} x\right)=x\right]$

Let, $y=\sin ^{-1}\left[x \sqrt{1-x}-\sqrt{x} \sqrt{1-x^{2}}\right]$
\begin{aligned}
&=\sin ^{-1}\left[x \sqrt{1-(\sqrt{x})^{2}}-\sqrt{x} \sqrt{1-x^{2}}\right] \\
&=\sin ^{-1} x-\sin ^{-1} \sqrt{x}
\end{aligned}

$\left[\mathrm{Using} \sin ^{-1} x-\sin ^{-1} y=\sin ^{-1}\left[x \sqrt{1-y^{2}}-y \sqrt{1-x^{2}}\right]\right.$

We have, $\tan (x+y)=33$
\begin{aligned}
&\Rightarrow \frac{\tan x+\tan y}{1-\tan x \tan y}=33 \\
&\Rightarrow \frac{3+\tan y}{1-3 \tan y}=33 \quad\left[\because x=\tan ^{-1} 3 \Rightarrow \tan x=3\right] \\
&\Rightarrow 3+\tan y=33-99 \tan y \\
&\Rightarrow 100 \tan y=30 \\
&\Rightarrow \tan y=\frac{3}{10} \\
&\Rightarrow y=\tan ^{-1} \frac{3}{10}
\end{aligned}

We have,

\begin{array}{ll}
\sin ^{-1}\left(\frac{2 p}{1+p^{2}}\right)-\cos ^{-1}\left(\frac{1-q^{2}}{1+q^{2}}\right) \\
& =\tan ^{-1}\left(\frac{2 x}{1+x^{2}}\right) \\
\Rightarrow & 2 \tan ^{-1} p-2 \tan ^{-1} q=2 \tan ^{-1} x \\
\Rightarrow & 2\left(\tan ^{-1} p-\tan ^{-1} q\right)=2 \tan ^{-1} x \\
\Rightarrow \quad & \tan ^{-1} p-\tan ^{-1} q=\tan ^{-1} x \\
\Rightarrow & \tan ^{-1}\left(\frac{p-q}{1+p q}\right)=\tan ^{-1} x \\
\Rightarrow & x=\frac{p-q}{1+p q}
\end{array}
